	"github.com/DocumentDrivenDX/fizeau/internal/provider/registry"
	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
)

const DefaultBaseURL = "http://localhost:1235/v1"

func init() {
	registry.Register(registry.Descriptor{
		Type: "omlx",
		Factory: func(in registry.Inputs) agentcore.Provider {
			return New(Config{
				BaseURL:      in.BaseURL,
				APIKey:       in.APIKey,
				Model:        in.Model,
				ModelPattern: in.ModelPattern,
				KnownModels:  in.KnownModels,
				Headers:      in.Headers,
				Reasoning:    in.Reasoning,
			})
		},
		DefaultBaseURL: DefaultBaseURL,
		DefaultPort:    1235,
	})
}

var ProtocolCapabilities = openai.ProtocolCapabilities{
	Tools:            true,
	Stream:           true,
	StructuredOutput: true,
	Thinking:         true,
	ThinkingFormat:   openai.ThinkingWireFormatQwen,
	// OMLX serves Qwen MLX variants exclusively, so an explicit reasoning
	// request against a non-Qwen model is a configuration bug worth failing
	// the request for. LM Studio hosts mixed families and keeps this false.
	StrictThinkingModelMatch: true,
}

type Config struct {
	BaseURL      string
	APIKey       string
	Model        string
	ModelPattern string
	KnownModels  map[string]string
	Headers      map[string]string
	Reasoning    reasoning.Reasoning
}

func New(cfg Config) *openai.Provider {
	baseURL := cfg.BaseURL
	if baseURL == "" {
		baseURL = DefaultBaseURL
	}
	return openai.New(openai.Config{
		BaseURL:        baseURL,
		APIKey:         cfg.APIKey,
		Model:          cfg.Model,
		ProviderName:   "omlx",
		ProviderSystem: "omlx",
		ModelPattern:   cfg.ModelPattern,
		KnownModels:    cfg.KnownModels,
		Headers:        cfg.Headers,
		Reasoning:      cfg.Reasoning,
		Capabilities:   &ProtocolCapabilities,
	})
}

func LookupModelLimits(ctx context.Context, baseURL, model string) limits.ModelLimits {
	base := strings.TrimRight(baseURL, "/")
	endpoint := base + "/models/status"

	var status struct {
		Models []struct {
			ID               string `json:"id"`
			MaxContextWindow int    `json:"max_context_window"`
			MaxTokens        int    `json:"max_tokens"`
		} `json:"models"`
	}
	if err := getAndDecode(ctx, 5*time.Second, endpoint, &status); err != nil {
		return limits.ModelLimits{}
	}

	for _, entry := range status.Models {
		if strings.EqualFold(entry.ID, model) {
			return limits.ModelLimits{
				ContextLength:       entry.MaxContextWindow,
				MaxCompletionTokens: entry.MaxTokens,
			}
		}
	}
	return limits.ModelLimits{}
}

func getAndDecode(ctx context.Context, timeout time.Duration, endpoint string, out any) error {
	reqCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	req, err := http.NewRequestWithContext(reqCtx, http.MethodGet, endpoint, nil)
	if err != nil {
		return err
	}
	req.Header.Set("Accept", "application/json")

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close() //nolint:errcheck

	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 256))
		return fmt.Errorf("HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	return json.NewDecoder(resp.Body).Decode(out)
}

// Package vllm wraps the OpenAI-compat HTTP surface exposed by `vllm serve`
// (https://docs.vllm.ai/). vLLM is a high-throughput inference server with
// one behavior worth distinguishing in the catalog stack: by default it
// applies the target model's HuggingFace `generation_config.json` when the
// client omits sampler fields. Most other local servers we wrap (omlx,
// lmstudio, lucebox) cannot do this — MLX / GGUF repackaging typically drops
// generation_config.json from the bundle, and the servers ship their own
// presets instead.
//
// The implication for ADR-007's catalog-stale nudge: when a vLLM-served
// request omits sampler fields, the user is not "decoding greedy" — the
// server is honoring the model creator's recommended bundle. The CLI
// reflects that with a softer message.
//
// Capabilities mirror lmstudio (Tools / Stream / StructuredOutput true) and
// add ImplicitGenerationConfig=true. Reasoning is model-dependent and not
// declared at the provider level; per-model thinking-mode controls live in
// the catalog ModelEntry, matching the lmstudio precedent.
//
// Default port 8000 follows the vLLM docs. Auth is optional: vLLM accepts
// unauthenticated requests by default and gates with --api-key (or
// VLLM_API_KEY) when the operator sets one. The Config.APIKey field flows
// through unchanged.
package vllm

import (
	agentcore "github.com/DocumentDrivenDX/fizeau/internal/core"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/openai"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/registry"
	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
)

const DefaultBaseURL = "http://localhost:8000/v1"

func init() {
	registry.Register(registry.Descriptor{
		Type: "vllm",
		Factory: func(in registry.Inputs) agentcore.Provider {
			return New(Config{
				BaseURL:      in.BaseURL,
				APIKey:       in.APIKey,
				Model:        in.Model,
				ModelPattern: in.ModelPattern,
				KnownModels:  in.KnownModels,
				Headers:      in.Headers,
				Reasoning:    in.Reasoning,
			})
		},
		DefaultBaseURL: DefaultBaseURL,
		DefaultPort:    8000,
	})
}

// ProtocolCapabilities mirrors lmstudio's openai-compat surface and adds
// ImplicitGenerationConfig=true so the catalog-stale nudge can soften.
var ProtocolCapabilities = openai.ProtocolCapabilities{
	Tools:                    true,
	Stream:                   true,
	StructuredOutput:         true,
	ImplicitGenerationConfig: true,
}

type Config struct {
	BaseURL      string
	APIKey       string
	Model        string
	ModelPattern string
	KnownModels  map[string]string
	Headers      map[string]string
	Reasoning    reasoning.Reasoning
}

