// MatcherFunc is a predicate, which returns true when the actual request
// matches an interaction from the cassette.
type MatcherFunc func(*http.Request, Request) bool

// MarshalFunc is a function which marshals an object to a byte slice.
type MarshalFunc func(any) ([]byte, error)

// defaultMatcher is the default matcher used to match HTTP requests with
// recorded interactions.
type defaultMatcher struct {
	// If set, the default matcher will ignore matching on any of the
	// defined headers.
	ignoreHeaders []string
}

// DefaultMatcherOption is a function which configures the default matcher.
type DefaultMatcherOption func(m *defaultMatcher)

// WithIgnoreUserAgent is a [DefaultMatcherOption], which configures the default
// matcher to ignore matching on the User-Agent HTTP header.
func WithIgnoreUserAgent() DefaultMatcherOption {
	opt := func(m *defaultMatcher) {
		m.ignoreHeaders = append(m.ignoreHeaders, "User-Agent")
	}

	return opt
}

// WithIgnoreAuthorization is a [DefaultMatcherOption], which configures the default
// matcher to ignore matching on the Authorization HTTP header.
func WithIgnoreAuthorization() DefaultMatcherOption {
	opt := func(m *defaultMatcher) {
		m.ignoreHeaders = append(m.ignoreHeaders, "Authorization")
	}

	return opt
}

// WithIgnoreHeaders is a [DefaultMatcherOption], which configures the default
// matcher to ignore matching on the defined HTTP headers.
func WithIgnoreHeaders(val ...string) DefaultMatcherOption {
	opt := func(m *defaultMatcher) {
		m.ignoreHeaders = append(m.ignoreHeaders, val...)
	}

	return opt
}

// NewDefaultMatcher returns the default matcher.
func NewDefaultMatcher(opts ...DefaultMatcherOption) MatcherFunc {
	m := &defaultMatcher{}
	for _, opt := range opts {
		opt(m)
	}

	return m.matcher
}

// Similar to reflect.DeepEqual, but considers the contents of collections, so
// {} and nil would be considered equal. works with Array, Map, Slice, or
// pointer to Array.
func (m *defaultMatcher) deepEqualContents(x, y any) bool {
	if reflect.ValueOf(x).IsNil() {
		if reflect.ValueOf(y).IsNil() {
			return true
		} else {
			return reflect.ValueOf(y).Len() == 0
		}
	} else {
		if reflect.ValueOf(y).IsNil() {
			return reflect.ValueOf(x).Len() == 0
		} else {
			return reflect.DeepEqual(x, y)
		}
	}
}

// bodyMatches is a predicate which tests whether the bodies of the given HTTP
// request and interaction request match.
func (m *defaultMatcher) bodyMatches(r *http.Request, i Request) bool {
	if r.Body != nil {
		var buffer bytes.Buffer
		if _, err := buffer.ReadFrom(r.Body); err != nil {
			return false
		}

		r.Body = io.NopCloser(bytes.NewBuffer(buffer.Bytes()))
		if buffer.String() != i.Body {
			return false
		}
	} else {
		if len(i.Body) != 0 {
			return false
		}
	}

	return true
}

// matcher is a predicate which matches the provided HTTP request again a
// recorded interaction request.
func (m *defaultMatcher) matcher(r *http.Request, i Request) bool {
	if r.Method != i.Method {
		return false
	}

	if r.URL.String() != i.URL {
		return false
	}

	if r.Proto != i.Proto {
		return false
	}

	if r.ProtoMajor != i.ProtoMajor {
		return false
	}

	if r.ProtoMinor != i.ProtoMinor {
		return false
	}

	requestHeader := r.Header.Clone()
	cassetteRequestHeaders := i.Headers.Clone()

	for _, header := range m.ignoreHeaders {
		delete(requestHeader, header)
		delete(cassetteRequestHeaders, header)
	}

	if !m.deepEqualContents(requestHeader, cassetteRequestHeaders) {
		return false
	}

	if !m.bodyMatches(r, i) {
		return false
	}

	if r.ContentLength != i.ContentLength {
		return false
	}

	if !m.deepEqualContents(r.TransferEncoding, i.TransferEncoding) {
		return false
	}

// WithMode is an [Option], which configures the [Recorder] to run in the
// specified mode.
func WithMode(mode Mode) Option {
	opt := func(r *Recorder) {
		r.mode = mode
	}

	return opt
}

// WithRealTransport is an [Option], which configures the [Recorder] to use the
// specified [http.RoundTripper] when making actual HTTP requests.
func WithRealTransport(rt http.RoundTripper) Option {
	opt := func(r *Recorder) {
		r.realTransport = rt
	}

	return opt
}

// WithBlockUnsafeMethods is an [Option], which configures the [Recorder] to
// block HTTP requests, which are not considered "Safe Methods", according to
// RFC 9110, section 9.2.1.
func WithBlockUnsafeMethods(val bool) Option {
	opt := func(r *Recorder) {
		r.blockUnsafeMethods = val
	}

	return opt
}

// WithSkipRequestLatency is an [Option], which configures the [Recorder] whether
// to simulate the latency of the recorded interaction. When set to false it
// will block for the period of time taken by the original request to simulate
// the latency between the recorder and the remote endpoints.
func WithSkipRequestLatency(val bool) Option {
	opt := func(r *Recorder) {
		r.skipRequestLatency = val
	}

	return opt
}

// WithPassthrough is an [Option], which configures the [Recorder] to
// passthrough requests for requests which satisfy the provided
// [PassthroughFunc] predicate.
func WithPassthrough(passfunc PassthroughFunc) Option {
	opt := func(r *Recorder) {
		r.passthroughs = append(r.passthroughs, passfunc)
	}

	return opt
}

// WithHook is an [Option], which configures the [Recorder] to invoke the
// provided hook at the specified playback stage.
func WithHook(handler HookFunc, kind HookKind) Option {
	opt := func(r *Recorder) {
		hook := NewHook(handler, kind)
		r.hooks = append(r.hooks, hook)
	}

	return opt
}

// WithMatchers is an [Option], which configures the [Recorder] to use the
// provided [MatcherFunc] predicate when matching HTTP requests against record
// interactions.
func WithMatcher(matcher MatcherFunc) Option {
	opt := func(r *Recorder) {
		r.matcher = matcher
	}

	return opt
}

// WithReplayableInteractions is an [Option], which configures the [Recorder] to
// allow replaying interactions multiple times. This is useful in situations
// when you need to hit the same endpoint multiple times and want to replay the
// interaction from the cassette each time.
func WithReplayableInteractions(val bool) Option {
	opt := func(r *Recorder) {
		r.replayableInteractions = val
	}

	return opt
}

// WithFS is an [Option], which configures the [Recorder] to use
// custom filesystem ([cassette.FS]) implementation. This allows the [Recorder] to use any
// FS-compatible backend (e.g., local disk, in-memory, or mock) for reading and writing files.
func WithFS(fs cassette.FS) Option {
	opt := func(r *Recorder) {
		r.fs = fs
	}

	return opt
}

// WithMarshalFunc is an [Option], which configures the [Recorder] to use
// custom YAML marshal func. This allows customization of the YAML encoding
// process, such as setting string literal style, etc.
func WithMarshalFunc(marshalFunc cassette.MarshalFunc) Option {
	return func(r *Recorder) {
		r.marshalFunc = marshalFunc
	}
}

// New creates a new [Recorder] and configures it using the provided options.
func New(cassetteName string, opts ...Option) (*Recorder, error) {
	r := &Recorder{
		cassetteName:           cassetteName,
		mode:                   ModeRecordOnce,
		realTransport:          http.DefaultTransport,
		passthroughs:           make([]PassthroughFunc, 0),
		hooks:                  make([]*Hook, 0),
		blockUnsafeMethods:     false,
		skipRequestLatency:     false,
		matcher:                cassette.DefaultMatcher,
		replayableInteractions: false,
		fs:                     cassette.NewDiskFS(),
		marshalFunc:            yaml.Marshal,
	}

	for _, opt := range opts {
		opt(r)
	}

	// Configure the cassette based on the recorder configuration
	c, err := r.getCassette()
	if err != nil {
		return nil, err
	}
	r.cassette = c
	r.cassette.Matcher = r.matcher
	r.cassette.ReplayableInteractions = r.replayableInteractions
	r.cassette.MarshalFunc = r.marshalFunc

	return r, nil
}

